html.chm-ready #champions>.panelhead,\nhtml.chm-ready #champions>.filters{display:none!important}\n\n/* ---------- control row: the engine sector tabs ---------- */\n.chm-controls{display:flex;align-items:center;gap:0;box-sizing:border-box;min-height:52px;padding:11px 0 18px;font:400 13px/1 var(--sans);color:var(--ml-ink)}\n.chm-controls__slot{display:flex;flex:none}\n.chm .mlk-seg.chm-seg--sector:not(#mlk)>button{padding:0 16px}\n.chm .mlk-seg:not(#mlk)>button[aria-pressed=true]{color:var(--ml-on-dark)!important;background:var(--ml-active)!important}\n.chm .mlk-seg:not(#mlk)>button{min-height:0!important;white-space:nowrap}\n\n/* fix r1 MD-2: restored.css paints every :focus-visible with the legacy purple accent (!important); inside the\n   board every ring is the kit's amber (fold summary -2px; the segments get theirs from ui-kit.css). */\nhtml.chm-ready .chm :focus-visible:not(#mlk){outline-color:var(--ml-accent)!important}\n\n/* ---------- tier board (shown open) and Most lobbied: collapsible sections ---------- */\n.chm-tiers{display:flex;flex-direction:column;gap:12px}\n.chm-folds{display:flex;flex-direction:column;gap:12px;margin-top:12px}\n.chm .chm-fold{margin:0;border:1px solid var(--ml-rule);border-radius:var(--ml-radius);background:var(--ml-surface)}\n.chm .chm-fold>summary{padding:12px 16px;color:var(--ml-ink);font:400 20px/1.2 var(--serif);cursor:pointer;list-style-position:inside}\n.chm .chm-fold[open]>summary{border-bottom:1px solid var(--ml-rule)}\n.chm .chm-fold>summary:focus-visible{outline:2px solid var(--ml-accent);outline-offset:-2px}\n.chm .chm-fold>:not(summary){margin:12px 16px 16px}\n.chm .chm-fold .mlk-seg:not(#mlk)>button{padding:0 14px}\n.chm .chm-fold #industry-tier-board-panel{padding:0;border:0;background:transparent}\n\n@media (max-width:1100px){\n  .chm-controls{flex-wrap:wrap;row-gap:10px}\n}\n", 'champions-ui.js': '/* champions-ui.js: overlay for original-champions.html (Champions, board #39); owner: prompt 12. Runs after the page engine, restored-links.js and ui-kit.js. */\n/* Overlay only: the engine\'s inline scripts and #page-data are untouched. The engine keeps its state\n   (currentSector) and its listeners; this file moves the engine\'s sector tabs into the control row,\n   shows the engine\'s tier board (Tier 1/2/3 for every industry), and moves the remaining sections below it.\n   The LDA lobbying-activity boards (Most supportive, Most opposed, Mixed record) are retired from display\n   (Paul 2026-10-27, "Remove them"); nothing stands in their place (Paul 2026-10-28) until contact\n   inference v1 ships. */\n(function () {\n  \'use strict\';\n  var K = window.MLK;\n  var root = document.getElementById(\'champions\');\n  if (!K || !root || typeof DATA === \'undefined\' || DATA.page !== \'champions\') return;\n\n  var els = {};\n\n  function legacyReady() {\n    return typeof renderIndustryTierBoard === \'function\' && typeof memberLink === \'function\';\n  }\n\n  /* ---------- build the frame (moves live engine nodes; nothing is deleted) ---------- */\n  function build() {\n    var wrap = document.createElement(\'div\');\n    wrap.className = \'chm\';\n    wrap.id = \'chm\';\n    wrap.innerHTML =\n      \'<div class="chm-controls" role="group" aria-label="Sector controls">\' +\n        \'<div class="chm-controls__slot" data-slot="sector"></div>\' +\n      \'</div>\' +\n      \'<div class="chm-tiers" data-slot="tiers"></div>\' +\n      \'<div class="chm-folds" data-slot="folds"></div>\';\n    root.insertBefore(wrap, root.firstChild);\n    els.wrap = wrap;\n\n    // Controls: the engine\'s own sector tabs (their listener stays attached).\n    var sector = document.getElementById(\'champion-sector-tabs\');\n    if (sector) {\n      sector.classList.remove(\'toggle\');\n      sector.classList.add(\'mlk-seg\', \'chm-seg--sector\');\n      wrap.querySelector(\'[data-slot="sector"]\').appendChild(sector);\n      // fix r1 MD-3: the engine\'s role=tablist gets tab keys (as the Industry and organization tablists have):\n      // ArrowLeft/ArrowRight (wrapping), Home and End move focus to that tab and click() it, so the engine\'s own\n      // click listener keeps currentSector and re-renders. Roving tabindex: only the selected tab is in the Tab order.\n      els.sectorTabs = sector;\n      sector.addEventListener(\'keydown\', function (e) {\n        var tab = e.target.closest && e.target.closest(\'[data-v2-sector]\');\n        if (!tab || !sector.contains(tab) || e.altKey || e.ctrlKey || e.metaKey) return;\n        var tabs = sectorTabs(), i = tabs.indexOf(tab), n = tabs.length;\n        var next = {ArrowRight: (i + 1) % n, ArrowLeft: (i - 1 + n) % n, Home: 0, End: n - 1}[e.key];\n        if (next === undefined || i < 0) return;\n        e.preventDefault();\n        var target = tabs[next];\n        target.focus();\n        if (target.getAttribute(\'aria-selected\') !== \'true\') target.click();\n        syncSectorTabs();\n      });\n      sector.addEventListener(\'click\', syncSectorTabs);   // runs after the engine\'s own click listener\n    }\n\n    // The tier board (Tier 1/2/3 for the selected industry) is the page\'s main content, shown open.\n    var tierPanel = document.getElementById(\'industry-tier-board-panel\');\n    var tierFold = tierPanel && tierPanel.closest(\'details\');\n    if (tierFold) { tierFold.open = true; tierFold.classList.add(\'chm-fold\'); wrap.querySelector(\'[data-slot="tiers"]\').appendChild(tierFold); }\n\n    // Most lobbied stays a collapsed section.\n    var folds = wrap.querySelector(\'[data-slot="folds"]\');\n    Array.prototype.forEach.call(root.querySelectorAll(\':scope > details.tierfold\'), function (d) {\n      d.classList.add(\'chm-fold\');\n      folds.appendChild(d);\n    });\n    var mode = root.querySelector(\'.toggle[aria-label="Champion score mode"]\');\n    if (mode) { mode.classList.remove(\'toggle\'); mode.classList.add(\'mlk-seg\', \'mlk-seg--sm\'); }\n  }\n\n  function sectorTabs() {\n    return els.sectorTabs ? Array.prototype.slice.call(els.sectorTabs.querySelectorAll(\'[data-v2-sector]\')) : [];\n  }\n  function syncSectorTabs() {\n    // The engine sets aria-selected on every sector change; the selected tab (or the first, if none is) takes tabindex 0.\n    var tabs = sectorTabs();\n    if (!tabs.length) return;\n    var sel = tabs.filter(function (t) { return t.getAttribute(\'aria-selected\') === \'true\'; })[0] || tabs[0];\n    tabs.forEach(function (t) { t.tabIndex = t === sel ? 0 : -1; });\n  }\n\n  /* ---------- start ---------- */\n  if (!legacyReady()) return;   // the engine did not come up: leave today\'s page as it is\n  build();\n  document.documentElement.classList.add(\'chm-ready\');\n  syncSectorTabs();\n  try { K.head.setInfo(null); } catch (e) { /* not framed */ }\n})();\n', 'desk-bills.css': "/* desk-bills.css: overlay for original-desk.html (Member desk > Bills, board #33); owner: prompt 05. Loaded after desk-profile.css. */\n/* Build 05 (board #33). Sizes are the board's (33_bills_table_drawer_v2.png, board px / 1.867): filter bar 52px with 30px\n   controls (search 252, Area 176, Congress 161, switch 42 x 22), 15-18px gaps; table header 42px; drawer 286px with a 17px gap,\n   in flow (the table narrows). Rows are the prompt's 40px (titles never wrap; the board's two-line rows are its Don't-copy).\n   Every colour is a --ml-* token; party dots reach --mlk-dot by reference from the desk's PTCOL (desk-bills.js). */\n\n/* legacy bills-view nodes (heading, intro, old controls row, count line, card grid) stay in the DOM, hidden */\n#view-bills .dbl-legacy{display:none!important}\nbody.restored-desk.dbl-page #view-bills.view:not(#mlk){padding-top:5px}\n\n.dbl-layout{display:grid;grid-template-columns:minmax(0,1fr);align-items:start;column-gap:17px;border-top:1px solid var(--ml-rule);color:var(--ml-ink);font:400 14px/1.3 var(--sans)}\n.dbl-layout.has-drawer{grid-template-columns:minmax(0,1fr) 286px}\n.dbl-main{min-width:0}\n\n/* ---------------- filter bar ---------------- */\n.dbl-filters{display:flex;align-items:center;flex-wrap:wrap;gap:10px 15px;box-sizing:border-box;min-height:52px;margin:0;padding:15px 0 7px 6px;border-left:1px solid var(--ml-rule);font:400 13px/1 var(--sans)}\n.dbl-filters .dbl-search:not(#mlk){width:252px}\n.dbl-filters .mlk-search__input:not(#mlk){height:30px}\n.dbl-filters .mlk-select:not(#mlk){height:30px}\n.dbl-filters .mlk-select:not(#mlk)>select{flex:1 1 auto;width:100%;min-width:0;text-overflow:ellipsis}\n.dbl-filters .dbl-sel--area:not(#mlk){width:176px}\n.dbl-filters .dbl-sel--congress:not(#mlk){width:161px}\n.dbl-pinned{display:inline-flex;align-items:center;gap:11px;margin-left:3px;color:var(--ml-ink);font:400 13px/1 var(--sans);white-space:nowrap;cursor:pointer;user-select:none}\n/* the legacy #billtracked checkbox, drawn as a switch (role=switch; its change handler is the legacy one) */\n.dbl-switch:not(#mlk){position:relative;flex:none;appearance:none;-webkit-appearance:none;box-sizing:border-box;width:42px;height:22px;min-height:0;margin:0;padding:0;border:1px solid var(--ml-control-border);border-radius:11px;background:var(--ml-surface);cursor:pointer;box-shadow:none}\n.dbl-switch:not(#mlk)::before{content:'';position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--ml-surface);box-shadow:0 0 0 1px var(--ml-control-border);transition:left .12s}\n.dbl-switch:not(#mlk):checked{background:var(--ml-active);border-color:var(--ml-active)}\n.dbl-switch:not(#mlk):checked::before{left:22px;box-shadow:none}\n.dbl-switch:not(#mlk):focus-visible{outline:2px solid var(--ml-accent)!important;outline-offset:2px}\n.dbl-count{margin-left:auto;color:var(--ml-muted);font:400 13px/1 var(--sans);white-space:nowrap;font-variant-numeric:tabular-nums}\n\n/* ---------------- table ---------------- */\n.dbl-card:not(#mlk){position:relative;margin-top:18px;overflow:clip}\n.dbl-table:not(#mlk){table-layout:fixed;min-width:720px;font-size:13px}\n.dbl-table col.dbl-c-bill{width:104px}\n.dbl-table col.dbl-c-areas{width:19%}\n.dbl-table col.dbl-c-sponsor{width:20%}\n.dbl-table col.dbl-c-congress{width:96px}\n.dbl-table col.dbl-c-cos{width:116px}\n.dbl-table:not(#mlk) th{height:42px;box-sizing:border-box;padding:0 12px;z-index:2}\n.dbl-table:not(#mlk) td{height:40px;padding:0 12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dbl-table:not(#mlk) :is(th,td):first-child{padding-left:14px}\n.dbl-table:not(#mlk) tr.dbl-row{cursor:pointer}\n.dbl-table:not(#mlk) tr.dbl-row:focus-visible{outline:2px solid var(--ml-accent)!important;outline-offset:-2px}\n.dbl-table:not(#mlk) tr.dbl-row.is-selected td{background:var(--ml-selection)}\n.dbl-table:not(#mlk) tr.dbl-row.is-selected td:first-child{box-shadow:inset 3px 0 0 var(--ml-active)}\n.dbl-table:not(#mlk) td.dbl-bill{font-weight:600}\n.dbl-ellip{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\n.dbl-sponsor .dbl-ellip{display:flex;align-items:center;gap:8px}\n.dbl-sponsor .dbl-ellip>.dbl-dot~*{min-width:0}\n.dbl-dot:not(#mlk){flex:none;width:9px;height:9px}\n.dbl-areas__in{display:flex;align-items:center;gap:6px;min-width:0;overflow:hidden}\n.dbl-area{display:block;flex:0 1 auto;min-width:0;box-sizing:border-box;height:24px;padding:0 8px;border:1px solid var(--ml-strong-rule);border-radius:var(--ml-radius);background:transparent;color:var(--ml-ink);font:400 12px/22px var(--sans);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dbl-area--more{flex:none;overflow:visible;color:var(--ml-muted)}\n.dbl-none{color:var(--ml-muted)}\n.dbl-table:not(#mlk) tr.dbl-skelrow td,.dbl-table:not(#mlk) tr.dbl-emptyrow td{height:auto;padding:0;white-space:normal}\n.dbl-table:not(#mlk) tr.dbl-skelrow .mlk-skel-row{height:40px}\n.dbl-table:not(#mlk) tr.dbl-emptyrow:hover td,.dbl-table:not(#mlk) tr.dbl-skelrow:hover td{background:transparent}\n.dbl-status:empty{display:none}\n.dbl-status .restore-loading:not(#mlk){position:static;inset:auto;margin:0;padding:14px 20px;border:0;border-top:1px solid var(--ml-rule);background:transparent;box-shadow:none;color:var(--ml-muted);font:400 13px/1.45 var(--sans);text-align:center;transform:none}\n.dbl-layout.is-error .dbl-status .restore-loading:not(#mlk){padding:28px 20px;border-top:0;color:var(--ml-ink);font-size:14px}\n.dbl-layout.is-error .dbl-status .mlk-btn:not(#mlk){margin:0 0 0 8px;height:30px}\n.dbl-more{margin-top:12px;text-align:center}\n.dbl-more .dbl-morebtn:not(#mlk){height:32px;font:500 13px/1 var(--sans)}\n.dbl-more .dbl-morebtn[hidden]{display:none!important}\n\n/* ---------------- drawer (in flow; sticks to the frame top; height set by desk-bills.js fit()) ---------------- */\n.dbl-drawer{position:sticky;top:0;display:flex;flex-direction:column;box-sizing:border-box;min-height:240px;border:1px solid var(--ml-rule);border-top:0;background:var(--ml-surface);color:var(--ml-ink);overflow:hidden}\n.dbl-drawer[hidden]{display:none!important}\n.dbl-drawer:focus-visible{outline:2px solid var(--ml-accent)!important;outline-offset:-2px}\n.dbl-drawer :focus-visible:not(#mlk){outline:2px solid var(--ml-accent)!important;outline-offset:2px}\n.dbl-d-scroll{flex:1 1 auto;min-height:0;overflow:auto;padding:22px 16px 16px;overscroll-behavior:contain}\n.dbl-d-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}\n.dbl-d-close:not(#mlk){width:24px;height:24px;margin:-5px -6px 0 0}\n.dbl-d-label:not(#mlk){margin:0;color:var(--ml-muted);font:500 11px/1.4 var(--sans)!important;letter-spacing:.06em!important;text-transform:uppercase!important}\n.dbl-d-title:not(#mlk){margin:12px 0 14px;color:var(--ml-ink);font:400 22px/28px var(--serif);letter-spacing:0}\n.dbl-d-sponsor{display:flex;align-items:center;gap:10px;margin:0 0 10px;font:400 14px/1.35 var(--sans)}\n.dbl-d-sponsor .dbl-dot:not(#mlk){width:11px;height:11px}\n.dbl-d-cos{margin:0 0 12px;font:400 14px/1.35 var(--sans)}\n.dbl-d-areas{display:flex;flex-wrap:wrap;gap:5px;margin:0 0 24px}\n.dbl-d-areas .dbl-area{height:27px;padding:0 11px;font:400 12px/25px var(--sans);max-width:100%}\n.dbl-d-h:not(#mlk){margin:0 0 8px}\n.dbl-d-summary{margin:0 0 12px;font:400 13px/1.45 var(--sans);overflow-wrap:anywhere}\n.dbl-d-stamp{margin:0 0 12px;color:var(--ml-muted);font:400 12px/1.4 var(--sans);overflow-wrap:anywhere}\n.dbl-d-people-wrap{margin:4px 0 12px;padding-top:12px;border-top:1px solid var(--ml-rule)}\n.dbl-d-people-wrap[hidden]{display:none}\n.dbl-d-sublabel:not(#mlk){margin:0 0 6px;color:var(--ml-muted);font:600 11px/1.4 var(--sans)!important;letter-spacing:.06em!important;text-transform:uppercase!important}\n.dbl-d-people{margin:0 0 12px;padding:0;list-style:none}\n.dbl-d-people li{display:flex;align-items:baseline;flex-wrap:wrap;gap:0 8px;padding:4px 0;border-bottom:1px solid var(--ml-rule);font:400 13px/1.35 var(--sans)}\n.dbl-d-people li:last-child{border-bottom:0}\n.dbl-d-people .dbl-dot:not(#mlk){align-self:center;width:8px;height:8px}\n.dbl-when{color:var(--ml-muted);font-size:12px}\n.dbl-d-empty{margin:0;color:var(--ml-muted);font:400 13px/1.4 var(--sans)}\n.dbl-d-more{margin:4px 0 0;border-top:1px solid var(--ml-rule)}\n.dbl-d-more>summary{padding:10px 0;color:var(--ml-ink);font:500 13px/1.3 var(--sans);cursor:pointer}\n.dbl-d-legacy{font-size:13px}\n.dbl-d-legacy .repo-cols{display:block}\n.dbl-d-legacy .repo-block{margin:0 0 12px}\n.dbl-d-legacy textarea.billnote{box-sizing:border-box;width:100%}\n.dbl-d-actions{flex:none;display:flex;flex-direction:column;gap:12px;padding:16px 16px 24px;background:var(--ml-surface)}\n.dbl-d-actions .mlk-btn:not(#mlk){width:100%;height:32px;font:500 13px/1 var(--sans)}\n.dbl-d-pin[aria-pressed=true]:not(#mlk){background:var(--ml-surface-alt)}\n.dbl-d-pin svg:not(#mlk){fill:currentColor;stroke:currentColor;stroke-width:1.2}\n.dbl-d-link{align-self:flex-start;margin-top:4px;color:var(--ml-active);font:400 13px/1.3 var(--sans);text-decoration:underline;text-underline-offset:3px}\n.dbl-drawer .mlk-state:not(#mlk){padding:28px 0}\n\n/* narrow frames: the drawer takes the full width under the filters (in flow, the table stays reachable above it) */\n@media (max-width:950px){\n .dbl-layout.has-drawer{grid-template-columns:minmax(0,1fr)}\n .dbl-drawer{position:relative;height:auto!important;max-height:none;border-top:1px solid var(--ml-rule);margin-top:16px;order:-1}\n .dbl-card:not(#mlk){overflow:auto}\n}\n@media (max-width:760px){\n .dbl-filters .dbl-search:not(#mlk),.dbl-filters .mlk-select:not(#mlk){width:100%}\n .dbl-count{margin-left:0}\n}\n", 'desk-bills.js': '/* desk-bills.js: overlay for original-desk.html (Member desk > Bills, board #33; the shell passes ?bill=<congress:type:number>); owner: prompt 05. Runs before restored-desk.js. */\n/* Build 05 (board #33). The legacy bill engine stays: BILLS / BILL_BY_KEY (rebuilt by rebuildBillRepository after the\n   desk-support merge), billStateFilter, billState / setBillState (localStorage mdesk_bill_tracker_v1), the legacy filter\n   controls (#billq, #billarea, #billcongress, #billtracked) and the Load-more button (#billmore) are MOVED into the new\n   filter bar with their handlers. renderBills is wrapped by name: instead of 40 tall cards it paints one-line table rows\n   with the legacy filter predicate, and the selected bill opens in an in-flow drawer (the table narrows). Pin uses the\n   legacy [data-pin] click handler; the legacy card body (coalition, lobbying, press, amendments, tracking notes) is kept\n   inside the drawer behind "Coalition, lobbying and notes" and keeps its legacy delegated handlers.\n   Data colours (party dots) are read by reference from the desk\'s PTCOL; no colour literal is typed here. */\n(() => {\n\'use strict\';\nconst Q = new URLSearchParams(location.search);\nif ((Q.get(\'deskview\') || \'ranked\') !== \'bills\') return;\nconst section = document.getElementById(\'view-bills\');\nif (!section || typeof renderBills !== \'function\' || typeof billStateFilter === \'undefined\') return;\nconst K = window.MLK || null;\nconst esc = v => (v == null ? \'\' : String(v)).replace(/[&<>"\']/g, c => ({\'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\', "\'": \'&#39;\'}[c]));\nconst $id = id => document.getElementById(id);\n\n/* ---------------- data helpers (same sources as the legacy billCard / renderBills) ---------------- */\nconst PARTY = {D: \'Democrat\', R: \'Republican\', I: \'Independent\', ID: \'Independent\', L: \'Independent\'};\nfunction partyColour(party){\n const name = PARTY[String(party || \'\').toUpperCase()] || party || \'\';\n const map = typeof PTCOL !== \'undefined\' ? PTCOL : (K && K.colorMap ? K.colorMap(\'PTCOL\') : null) || {};\n return map[name] || map[\'\'] || \'\';\n}\nconst dot = party => { const c = partyColour(party); return `<span class="mlk-dot dbl-dot" aria-hidden="true"${c ? ` style="--mlk-dot:${esc(c)}"` : \'\'}></span>`; };\n/* "Rep. Gonzalez, Vicente [D-TX-34]" -> "Rep. Gonzalez [D-TX-34]" (display only; the full name stays in the drawer) */\nfunction shortName(name){\n const s = String(name || \'\').trim();\n const m = s.match(/^((?:Rep|Sen|Del)\\.|Resident Commissioner)\\s+([^,\\[]+?)\\s*,[^\\[]*?(\\[[^\\]]*\\])\\s*$/);\n return m ? `${m[1]} ${m[2]} ${m[3]}` : s;\n}\nfunction memberIndex(bioguide, name){\n if (bioguide && K && K.memberByIdSync){ const row = K.memberByIdSync(bioguide); if (row && typeof byName !== \'undefined\' && byName[row.name] != null) return byName[row.name]; }\n if (bioguide){\n  if (!memberIndex.map){ memberIndex.map = {}; M.forEach((m, i) => { const b = (m.bio || {}).bioguide || m.bioguide; if (b) memberIndex.map[b] = i; }); }\n  if (memberIndex.map[bioguide] != null) return memberIndex.map[bioguide];\n }\n return name != null && typeof byName !== \'undefined\' && byName[name] != null ? byName[name] : null;\n}\nfunction sponsorOf(bill){\n const live = bill.live || {}, s = live.sponsor || {};\n if (s.name) return {name: s.name, party: s.party || \'\', bioguide: s.bioguide || \'\'};\n const i = (bill.sponsors || [])[0];\n if (i != null && M[i]) return {name: M[i].name, party: M[i].party || \'\', mi: i};\n return bill.sponsor ? {name: bill.sponsor, party: \'\'} : null;\n}\n/* the legacy billCard count: unique originals + later cosponsors not already original (live lists first) */\nfunction cosponsorsOf(bill){\n const live = bill.live || {};\n const uniq = rows => { const seen = new Set(), out = []; rows.forEach(r => { const n = String(r.name || \'\').trim(); if (n && !seen.has(n)){ seen.add(n); out.push(r); } }); return out; };\n const fromIdx = idx => (idx || []).map(i => ({name: M[i].name, party: M[i].party || \'\', mi: i}));\n const originals = uniq(Array.isArray(live.original_cosponsors) ? live.original_cosponsors : fromIdx(bill.originals));\n const on = new Set(originals.map(r => String(r.name).trim()));\n const later = uniq(Array.isArray(live.cosponsors) ? live.cosponsors : fromIdx(bill.cosponsors)).filter(r => !on.has(String(r.name).trim()));\n return {originals, later, count: originals.length + later.length};\n}\n/* the legacy renderBills predicate, unchanged */\nfunction matchesFor(){\n const f = billStateFilter, q = f.q;\n return BILLS.filter(b => (!q || (`${b.display} ${b.title} ${b.sponsor}`).toLowerCase().includes(q)) && (!f.area || (b.areas || []).includes(f.area)) && (!f.congress || String(b.congress) === f.congress) && (!f.tracked || billState(b.key).pinned));\n}\nfunction cacheStamp(bill){\n const live = bill && bill.live, all = (typeof D !== \'undefined\' && D.bill_live) || {};\n const at = (live && live.updated_at) || all.updated_at;\n if (!at) return \'Congress.gov live cache not yet synced\';\n return `Congress.gov ${live && live.stale ? \'last good copy\' : \'live cache\'} ${at}`;\n}\nfunction resolveBill(raw){\n const v = String(raw || \'\').trim(); if (!v) return null;\n if (BILL_BY_KEY[v]) return BILL_BY_KEY[v];\n const low = v.toLowerCase(); if (BILL_BY_KEY[low]) return BILL_BY_KEY[low];\n const flat = low.replace(/[^a-z0-9]/g, \'\');\n return BILLS.find(b => String(b.display).toLowerCase().replace(/[^a-z0-9]/g, \'\') === flat) || null;\n}\n\n/* ---------------- layout (built once; legacy nodes moved in) ---------------- */\ndocument.body.classList.add(\'dbl-page\');\nconst legacyNodes = [...section.children];\nlegacyNodes.forEach(n => n.classList.add(\'dbl-legacy\'));\nconst layout = document.createElement(\'div\');\nlayout.className = \'dbl-layout\';\nlayout.innerHTML = `\n<div class="dbl-main">\n <div class="dbl-filters" role="search" aria-label="Bill filters">\n  <div class="mlk-search dbl-search"></div>\n  <label class="mlk-select dbl-sel dbl-sel--area"><span class="mlk-select__label">Area:</span></label>\n  <label class="mlk-select dbl-sel dbl-sel--congress"><span class="mlk-select__label">Congress:</span></label>\n  <label class="dbl-pinned"><span class="dbl-pinned__text">Pinned only</span></label>\n  <span class="dbl-count" id="dbl-count" role="status" aria-live="polite"></span>\n </div>\n <div class="mlk-tablecard dbl-card">\n  <table class="mlk-table dbl-table" aria-describedby="dbl-count">\n   <colgroup><col class="dbl-c-bill"><col class="dbl-c-title"><col class="dbl-c-areas"><col class="dbl-c-sponsor"><col class="dbl-c-congress"><col class="dbl-c-cos"></colgroup>\n   <thead><tr><th scope="col">Bill</th><th scope="col">Title</th><th scope="col">Areas</th><th scope="col">Sponsor</th><th scope="col">Congress</th><th scope="col">Cosponsors</th></tr></thead>\n   <tbody id="dbl-rows"></tbody>\n  </table>\n  <div class="dbl-status" id="dbl-status"></div>\n </div>\n <div class="dbl-more"></div>\n</div>\n<aside class="dbl-drawer" id="dbl-drawer" aria-label="Bill detail" tabindex="-1" hidden></aside>`;\nsection.append(layout);\nconst rowsEl = $id(\'dbl-rows\'), statusEl = $id(\'dbl-status\'), drawer = $id(\'dbl-drawer\'), countEl = $id(\'dbl-count\');\n\nconst q = $id(\'billq\'), area = $id(\'billarea\'), congress = $id(\'billcongress\'), tracked = $id(\'billtracked\'), more = $id(\'billmore\');\nconst searchBox = layout.querySelector(\'.dbl-search\');\nif (K && K.icon) searchBox.innerHTML = K.icon(\'search\').replace(\'<svg\', \'<svg class="mlk-search__icon" aria-hidden="true"\');\nif (q){ q.classList.add(\'mlk-search__input\'); q.placeholder = \'Bill, title, sponsor\'; q.setAttribute(\'aria-label\', \'Search bills by bill, title or sponsor\'); searchBox.append(q); }\nif (area){ area.setAttribute(\'aria-label\', \'Area\'); layout.querySelector(\'.dbl-sel--area\').append(area); }\nif (congress){ congress.setAttribute(\'aria-label\', \'Congress\'); layout.querySelector(\'.dbl-sel--congress\').append(congress); }\nif (tracked){ tracked.classList.add(\'dbl-switch\'); tracked.setAttribute(\'role\', \'switch\'); tracked.setAttribute(\'aria-label\', \'Pinned only\'); layout.querySelector(\'.dbl-pinned\').prepend(tracked); }\nif (more){ more.className = \'mlk-btn dbl-morebtn\'; layout.querySelector(\'.dbl-more\').append(more); }\nfunction relabel(){\n if (area && area.options[0] && area.options[0].value === \'\') area.options[0].textContent = \'All areas\';\n if (congress) [...congress.options].forEach(o => { o.textContent = o.value === \'\' ? \'All\' : `${o.value}th`; });\n}\n\n/* ---------------- states ---------------- */\nconst SKELETON = Array.from({length: 8}, () => \'<tr class="dbl-skelrow" aria-hidden="true"><td colspan="6"><div class="mlk-skel-row"><span class="mlk-skel"></span><span class="mlk-skel"></span><span class="mlk-skel"></span><span class="mlk-skel"></span></div></td></tr>\').join(\'\');\nlet loaded = false;\nfunction showLoading(){ loaded = false; layout.classList.remove(\'is-error\'); layout.setAttribute(\'aria-busy\', \'true\'); rowsEl.innerHTML = SKELETON; countEl.textContent = \'\'; if (more){ more.style.display = \'none\'; more.hidden = true; } }\n/* restored-desk.js appends p.restore-loading ("Loading bill and staff records…"; on failure the message + Retry). It is\n   moved into the table card; its Retry keeps restored-desk\'s handler (it removes the line and loads again). */\nfunction adopt(node){\n if (!(node instanceof HTMLElement) || !node.classList.contains(\'restore-loading\')) return;\n statusEl.append(node); node.classList.add(\'mlk-state\');\n const sync = () => { const failed = !!node.querySelector(\'button\'); node.classList.toggle(\'mlk-state--error\', failed); layout.classList.toggle(\'is-error\', failed); if (failed){ layout.removeAttribute(\'aria-busy\'); rowsEl.innerHTML = \'\'; node.setAttribute(\'role\', \'alert\'); node.querySelectorAll(\'button\').forEach(b => b.classList.add(\'mlk-btn\')); } };\n sync(); new MutationObserver(sync).observe(node, {childList: true, subtree: true, characterData: true});\n}\nnew MutationObserver(list => list.forEach(r => r.addedNodes.forEach(n => { if (n.parentNode === document.body) adopt(n); }))).observe(document.body, {childList: true});\n[...document.querySelectorAll(\'body > p.restore-loading\')].forEach(adopt);\n\n/* ---------------- table ---------------- */\nlet selected = null;   // key of the bill in the drawer\nfunction areaChips(list, max){\n const a = list || [], shown = max ? a.slice(0, max) : a, rest = a.length - shown.length;\n return shown.map(x => `<span class="dbl-area">${esc(x)}</span>`).join(\'\') + (rest > 0 ? `<span class="dbl-area dbl-area--more" aria-label="${rest} more">+${rest}</span>` : \'\');\n}\nfunction rowHTML(b){\n const s = sponsorOf(b), c = cosponsorsOf(b), sel = b.key === selected;\n const title = b.title || b.display, areas = (b.areas || []).join(\', \');\n return `<tr data-key="${esc(b.key)}" tabindex="0" class="dbl-row${sel ? \' is-selected\' : \'\'}"${sel ? \' aria-current="true"\' : \'\'}>\n<td class="dbl-bill">${esc(b.display)}</td>\n<td class="dbl-title"><span class="dbl-ellip" title="${esc(title)}">${esc(title)}</span></td>\n<td class="dbl-areas"${areas ? ` title="${esc(areas)}"` : \'\'} data-n="${(b.areas || []).length}"><span class="dbl-areas__in">${areaChips(b.areas, 2) || \'<span class="dbl-none">—</s